# Area Calculator

A small, self-contained Python script that computes the area of several common shapes, either by calling its functions directly or through an interactive menu.

```python
#!/usr/bin/env python3
"""
area_calculator.py

Compute the area of common 2-D shapes.

Usage:
    python area_calculator.py          # interactive menu
    python area_calculator.py circle 3  # one-shot: area of a circle with r = 3
"""

import math
from typing import Callable

# ----------------------------------------------------------------- shapes ---

def circle(radius: float) -> float:
    """Area of a circle: πr²"""
    if radius < 0:
        raise ValueError("Radius cannot be negative.")
    return math.pi * radius ** 2


def square(side: float) -> float:
    """Area of a square: s²"""
    if side < 0:
        raise ValueError("Side cannot be negative.")
    return side ** 2


def rectangle(length: float, width: float) -> float:
    """Area of a rectangle: l × w"""
    if length < 0 or width < 0:
        raise ValueError("Length and width cannot be negative.")
    return length * width


def triangle(base: float, height: float) -> float:
    """Area of a triangle: ½ × b × h"""
    if base < 0 or height < 0:
        raise ValueError("Base and height cannot be negative.")
    return 0.5 * base * height


def trapezoid(a: float, b: float, height: float) -> float:
    """Area of a trapezoid: ½(a + b)h"""
    if a < 0 or b < 0 or height < 0:
        raise ValueError("Dimensions cannot be negative.")
    return 0.5 * (a + b) * height


def parallelogram(base: float, height: float) -> float:
    """Area of a parallelogram: b × h"""
    if base < 0 or height < 0:
        raise ValueError("Dimensions cannot be negative.")
    return base * height


def ellipse(a: float, b: float) -> float:
    """Area of an ellipse: πab"""
    if a < 0 or b < 0:
        raise ValueError("Semi-axes cannot be negative.")
    return math.pi * a * b


def regular_polygon(n: int, side: float) -> float:
    """Area of a regular n-gon: (n·s²) / (4·tan(π/n))"""
    if n < 3:
        raise ValueError("A polygon needs at least 3 sides.")
    if side < 0:
        raise ValueError("Side length cannot be negative.")
    return (n * side ** 2) / (4 * math.tan(math.pi / n))


# ------------------------------------------------------------------ menu ----

SHAPES: dict[str, tuple[str, list[tuple[str, str]], Callable[..., float]]] = {
    "circle":          ("Circle (r)",              [("radius", "Radius")],                          circle),
    "square":          ("Square (s)",               [("side", "Side")],                              square),
    "rectangle":       ("Rectangle (l, w)",         [("length", "Length"), ("width", "Width")],      rectangle),
    "triangle":        ("Triangle (b, h)",          [("base", "Base"), ("height", "Height")],         triangle),
    "trapezoid":       ("Trapezoid (a, b, h)",      [("a", "Parallel side a"), ("b", "Parallel side b"),
                                                      ("height", "Height")],                          trapezoid),
    "parallelogram":   ("Parallelogram (b, h)",     [("base", "Base"), ("height", "Height")],         parallelogram),
    "ellipse":         ("Ellipse (a, b)",           [("a", "Semi-major axis"), ("b", "Semi-minor axis")], ellipse),
    "polygon":         ("Regular polygon (n, s)",   [("n", "Number of sides"), ("side", "Side")],    regular_polygon),
}


def ask_float(prompt: str) -> float:
    """Prompt until the user enters a valid number."""
    while True:
        try:
            return float(input(prompt).strip())
        except ValueError:
            print("  ! Please enter a number.")


def ask_int(prompt: str) -> int:
    """Prompt until the user enters a valid integer."""
    while True:
        try:
            return int(input(prompt).strip())
        except ValueError:
            print("  ! Please enter a whole number.")


def calculate(name: str) -> float:
    """Ask for the dimensions of `name` and return its area."""
    label, params, func = SHAPES[name]
    print(f"\n{label}")
    values = []
    for key, description in params:
        prompt = f"  {description}: "
        value = ask_int(prompt) if key == "n" else ask_float(prompt)
        values.append(value)
    return func(*values)


def main() -> None:
    print("=" * 42)
    print("        AREA CALCULATOR")
    print("=" * 42)
    for i, (name, (label, _, _)) in enumerate(SHAPES.items(), start=1):
        print(f"  {i}. {label}")
    print("  0. Quit")

    while True:
        choice = input("\nChoose a shape (number or name): ").strip().lower()
        if choice in {"0", "q", "quit", "exit"}:
            print("Bye!")
            break

        name = next((k for k in SHAPES if k == choice), None)
        if name is None and choice.isdigit() and 1 <= int(choice) <= len(SHAPES):
            name = list(SHAPES)[int(choice) - 1]

        if name is None:
            print("  ! Unknown choice.")
            continue

        try:
            area = calculate(name)
            print(f"  => Area = {area:.4f} square units\n")
        except ValueError as exc:
            print(f"  ! Error: {exc}\n")


if __name__ == "__main__":
    main()
```

### Notes

- **Formulas used**

  | Shape | Formula |
  |---|---|
  | Circle | πr² |
  | Square | s² |
  | Rectangle | l·w |
  | Triangle | ½bh |
  | Trapezoid | ½(a + b)h |
  | Parallelogram | bh |
  | Ellipse | πab |
  | Regular polygon | ns² / (4·tan(π/n)) |

- **Example — one-shot mode from a shell:**

  ```
  $ python area_calculator.py circle 3
  28.274333882308138
